    private static void DeclareCompletionSourceSchema(CompanyPPDMRowAccessTests.Fixture f)
    {
        var creator=new ClassCreator(f.Editor.Object);f.Editor.SetupGet(value=>value.classCreator).Returns(creator);        foreach(var (type,keys) in new[]{(typeof(WORK_ORDER_INSPECTION),new[]{"INSPECTION_ID"}),(typeof(COMPANY_PERSONNEL_IDENTITY),new[]{"IDENTITY_RECORD_ID"}),(typeof(BA_EMPLOYEE),new[]{"EMPLOYER_BA_ID","EMPLOYEE_BA_ID","EMPLOYEE_OBS_NO"}),(typeof(BUSINESS_ASSOCIATE),new[]{"BUSINESS_ASSOCIATE_ID"})})
        {
            var table=type.Name;var shape=creator.ConvertToEntityStructure(type);foreach(var field in shape.Fields){field.IsKey=keys.Contains(field.FieldName);if(field.IsKey)field.AllowDBNull=false;}
            var metadata=new PPDMTableMetadata{TableName=table,EntityTypeName=type.Name,PrimaryKeyColumn=string.Join(',',keys),Module="PPDM_CORE"};foreach(var column in table=="BA_EMPLOYEE"?new[]{"EMPLOYER_BA_ID","EMPLOYEE_BA_ID"}:table=="COMPANY_PERSONNEL_IDENTITY"?new[]{"PERSON_BA_ID","OWNER_COMPANY_BA_ID"}:Array.Empty<string>())metadata.ForeignKeys.Add(new(){ForeignKeyColumn=column,ReferencedTable="BUSINESS_ASSOCIATE",ReferencedPrimaryKey="BUSINESS_ASSOCIATE_ID"});
            f.Source.Setup(value=>value.CheckEntityExist(table)).Returns(true);f.Source.Setup(value=>value.GetEntityStructure(It.Is<EntityStructure>(value=>value.EntityName==table),true)).Returns(shape);f.Metadata.Setup(value=>value.GetTableMetadataAsync(table)).ReturnsAsync(metadata);f.Metadata.Setup(value=>value.GetPrimaryKeyColumnsAsync(table)).ReturnsAsync(keys);
        }
    }

    private static async Task VerifyReturnHandoffHttp(HttpHost host,string reviewUrl,CompanyWorkOrderCompletionQuery query,CompanyPPDMRowAccessTests.Fixture f,string actor,CompanyWorkOrderCompletionDecisionRecovery decision)
    {
        var url=reviewUrl[..^"/review".Length];var writes=f.Writes.Count;using var response=await host.Http.PostAsJsonAsync(reviewUrl,query);Assert.True(response.StatusCode==HttpStatusCode.OK,await response.Content.ReadAsStringAsync());var review=(await response.Content.ReadFromJsonAsync<CompanyMaintenanceReturnHandoffReview>())!;review.Require();Assert.Equal("FacilityRole",review.NextRole);Assert.Equal(writes,f.Writes.Count);
        var command=new CompanyMaintenanceReturnHandoffCommand(review,Guid.NewGuid(),"Original verified work handed to configured return approver");using(var missing=await host.Http.PostAsJsonAsync(url+"/recovery/reference",command.Reference()))Assert.Equal(HttpStatusCode.Conflict,missing.StatusCode);Assert.Equal(writes,f.Writes.Count);
        var report=JsonSerializer.Serialize(f.Rows.OfType<WORK_ORDER_EXECUTION_SUBMISSION>().Single());using var recorded=await host.Http.PostAsJsonAsync(url,command);Assert.True(recorded.StatusCode==HttpStatusCode.OK,await recorded.Content.ReadAsStringAsync());Assert.Equal("no-store",recorded.Headers.CacheControl?.ToString());var saved=(await recorded.Content.ReadFromJsonAsync<CompanyMaintenanceReturnHandoffRecovery>())!;saved.Require(review.Stage.Context.Company,actor,command.Reference());Assert.Equal(writes+9,f.Writes.Count);writes=f.Writes.Count;
        Assert.Equal(2,saved.Receipt.ClosedTaskIds.Count);Assert.Equal(2,saved.Receipt.ReturnTaskIds.Count);Assert.Equal("return",f.Rows.OfType<PROCESS_INSTANCE>().Single().CURRENT_STEP_ID);Assert.Equal(report,JsonSerializer.Serialize(f.Rows.OfType<WORK_ORDER_EXECUTION_SUBMISSION>().Single()));
        foreach(var (path,body) in new[]{(url,(object)command),(url+"/recovery/reference",(object)command.Reference())}){using var retry=await host.Http.PostAsJsonAsync(path,body);Assert.True(retry.StatusCode==HttpStatusCode.OK,await retry.Content.ReadAsStringAsync());Assert.Equal(JsonSerializer.Serialize(saved),JsonSerializer.Serialize(await retry.Content.ReadFromJsonAsync<CompanyMaintenanceReturnHandoffRecovery>()));Assert.Equal(writes,f.Writes.Count);}
        using(var replacement=await host.Http.PostAsJsonAsync(url,command with{IntentId=Guid.NewGuid()}))Assert.Equal(HttpStatusCode.Conflict,replacement.StatusCode);Assert.Equal(writes,f.Writes.Count);
        using var prior=await host.Http.PostAsJsonAsync(host.Url+"/api/field/current/maintenance-handoffs/execution-permit/completion-decision/recovery/reference",decision.Command.Reference());Assert.True(prior.StatusCode==HttpStatusCode.OK,await prior.Content.ReadAsStringAsync());Assert.Equal(JsonSerializer.Serialize(decision),JsonSerializer.Serialize(await prior.Content.ReadFromJsonAsync<CompanyWorkOrderCompletionDecisionRecovery>()));Assert.Equal(writes,f.Writes.Count);
    }
    private sealed class CompletionDecisionExceptionObserver:Microsoft.AspNetCore.Diagnostics.IExceptionHandler
    {
        internal Exception? Last;
        public ValueTask<bool> TryHandleAsync(Microsoft.AspNetCore.Http.HttpContext context,Exception error,CancellationToken cancellationToken){Last=error;return ValueTask.FromResult(false);}
        internal string Detail()=>Last is null?"":Last.GetType().FullName+": "+Last.Message+Environment.NewLine+Last.StackTrace;
    }
